#include "eternity/game/interface_save.hpp"
#include "eternity/game/quest_save.hpp"
#include "eternity/game/skill_save.hpp"
#include "eternity/game/character_core_save.hpp"
#include "eternity/game/inventory_save.hpp"
#include "eternity/game/creation.hpp"
#include <bit>
#include <iostream>
#include <limits>

using namespace eternity;using namespace eternity::game;
namespace {
void require(bool value,const char* message) {if(!value) throw std::runtime_error(message);}
void put(net::Packet& p,std::uint32_t value,unsigned int count) {for(unsigned int i=0;i<count;++i) p.push_back(static_cast<std::uint8_t>(value>>(8*i)));}
net::Packet packet(std::uint16_t op) {net::Packet p;put(p,op,2);put(p,9401,4);return p;}
net::Packet point(std::uint8_t slot,std::uint16_t map,float x,float y,float z) {auto p=packet(0xd02);p.push_back(slot);put(p,map,2);for(float value:{x,y,z}) put(p,std::bit_cast<std::uint32_t>(value),4);return p;}
net::Packet quick(std::initializer_list<std::uint16_t> numbers) {auto p=packet(0x609);p.push_back(static_cast<std::uint8_t>(numbers.size()));for(auto n:numbers) {p.insert(p.end(),{1,2,3});put(p,n,2);}return p;}
net::Packet money(std::uint32_t value) {auto p=packet(0x603);put(p,value,4);return p;}
net::Packet skill(std::uint16_t id,std::uint16_t points) {auto p=packet(0x801);put(p,points,2);put(p,id,2);p.push_back(1);return p;}
net::Packet quest(std::uint16_t delay) {auto p=packet(0xa03);put(p,10,2);put(p,delay,2);p.insert(p.end(),{1,2,3});return p;}
}
int main(int argc,char** argv) {
    try {
        require(argc==2 && std::string_view(argv[1]).starts_with("Eternity_Test_Creation_"),"Interface SQL test requires disposable catalog");const std::string catalog=argv[1],prefix="["+catalog+"].dbo.";
        storage::SqlServer db(storage::SqlServerConfig::from_environment());const auto definitions=Definitions::load(db);const auto rules=CreationRules::load(definitions);const auto time=std::chrono::sys_days{std::chrono::year{2024}/1/1};Characters characters(db,1,time,catalog);require(characters.save_country(9401,0,true) && characters.save_country(9402,0,true),"Cannot initialize interface fixture factions");auto draft=rules.prepare({0,0,0,0,0,0,0,0,"InterfaceHero"},0);draft.items.clear();const auto created=characters.create(9401,"ui_user",draft,time);draft.request.name="InterfaceOther";const auto other=characters.create(9402,"ui_other",draft,time);require(created.result==0 && other.result==0,"Cannot create interface fixture characters");const auto cid=std::to_string(created.character_id),other_id=std::to_string(other.character_id);
        db.query("EXEC "+prefix+"usp_Save_Char_QuickSlot_Add_E "+cid+",1,2,3,9; EXEC "+prefix+"usp_Create_Char_SavePoint "+cid+",1,1,10.5,20.5,30.5; EXEC "+prefix+"usp_Save_Char_QuickSlot_Add_E "+other_id+",7,8,9,10; EXEC "+prefix+"usp_Create_Char_SavePoint "+other_id+",3,9,1,2,3;");
        PlayerSnapshot initial;initial.core.user_id=9401;initial.core.character=draft.character;initial.core.character.id=created.character_id;initial.core.skill_points=40;initial.quick_slots={{1,2,3,9}};initial.save_points={{1,1,10.5F,20.5F,30.5F}};InventoryReplicaPool pool;CharacterReplica cache(initial.core,pool);require(cache.interface().load(initial),"Cannot load typed interface state");
        CharacterCoreStore core_store(db,catalog);InventoryStore items(db,1,catalog);SkillStore skills(db,catalog);QuestStore quests(db,catalog);InterfaceStore ui(db,catalog);unsigned int logs=0;
        const auto apply=[&](const net::Packet& p){require(cache.apply(p)==InventoryReplicaResult::applied,"Interface fixture packet failed");};
        const auto save=[&](bool save_quick){core_store.save_in_transaction(cache);items.save_in_transaction(cache.inventory(),created.character_id);skills.save_in_transaction(cache.skills(),created.character_id);quests.save_in_transaction(cache.quests(),created.character_id);return ui.save_in_transaction(cache.interface(),created.character_id,save_quick,[&](std::string_view text){require(!text.empty(),"Quick diagnostic was empty");++logs;});};
        const auto ack=[&](){cache.core_save_success();cache.inventory().inventory_save_success();cache.skills().save_success();cache.quests().save_success();cache.interface().save_success();};
        const auto read_quick=[&](){return db.query("SELECT QuickBar,QuickSlot,Bag,Number FROM "+prefix+"CharQuickSlots WHERE CharID="+cid+" ORDER BY Number;")[0].rows;};
        bool rejected=false;try{ui.save_in_transaction(cache.interface(),created.character_id,true);}catch(const std::logic_error&){rejected=true;}require(rejected,"Interface phase ran outside complete character transaction");
        apply(point(1,2,0.0078125F,-std::numeric_limits<float>::denorm_min(),std::bit_cast<float>(0x3f800001U)));apply(point(0,3,42,-0.0F,13));apply(quick({7,8}));apply(money(55));apply(skill(5,20));auto start=packet(0xa01);put(start,10,2);put(start,1,2);apply(start);PlayerItem item;item.uid=0x7777000000000600ULL;item.id=5001;item.type=5;item.type_id=1;item.bag=1;item.count=10;item.made_at=pack_world_time(time);item.make_type="U";require(cache.inventory().load(item,false,1),"Cannot seed interface composite item");
        require(cache.interface().points()[0].save_type==1 && cache.interface().points()[1].save_type==2,"New/existing point classification changed");db.begin();auto result=save(false);require(!result.quick_failure && cache.interface().points()[0].save_type==1,"Periodic interface save acknowledged early or saved quick slots");db.commit();ack();
        auto rows=db.query("SELECT Slot,MapID,CONVERT(int,CONVERT(binary(4),PosX)),CONVERT(int,CONVERT(binary(4),PosY)),CONVERT(int,CONVERT(binary(4),PosZ)) FROM "+prefix+"CharSavePoint WHERE CharID="+cid+" ORDER BY Slot;");require(rows[0].rows.size()==2 && rows[0].rows[0][0]==storage::Cell{"0"} && rows[0].rows[0][1]==storage::Cell{"3"} && rows[0].rows[1]==storage::Row{storage::Cell{"1"},storage::Cell{"2"},storage::Cell{std::to_string(std::bit_cast<std::uint32_t>(0.007813F))},storage::Cell{"0"},storage::Cell{"1065353216"}},"Point insert/update/legacy coordinate rounding changed");require(read_quick()==std::vector<storage::Row>{{storage::Cell{"1"},storage::Cell{"2"},storage::Cell{"3"},storage::Cell{"9"}}},"Periodic save unexpectedly wrote quick slots");
        db.begin();result=save(true);db.commit();ack();require(!result.quick_failure && read_quick().size()==2 && read_quick()[0][3]==storage::Cell{"7"} && read_quick()[1][3]==storage::Cell{"8"},"Explicit quick replacement failed");
        // Quick failures are nonfatal and stop remaining quick inserts; points still save.
        apply(quick({11,65535,12}));apply(point(2,4,1,2,3));apply(money(77));apply(skill(6,10));auto count=packet(0x707);count.insert(count.end(),{1,0,4});apply(count);apply(quest(2));db.begin();result=save(true);require(result.quick_failure && logs==1,"Quick error was not reported immediately");db.commit();ack();require(read_quick().size()==1 && read_quick()[0][3]==storage::Cell{"11"} && cache.interface().quick_slots().size()==3 && cache.interface().points()[2].save_type==0,"Original partial quick save/point acknowledgment changed");
        rows=db.query("SELECT Money,SkillPoint FROM "+prefix+"Chars WHERE CharID="+cid+"; SELECT [Count] FROM "+prefix+"CharItems WHERE CharID="+cid+"; SELECT [Delay] FROM "+prefix+"CharQuests WHERE CharID="+cid+"; SELECT MapID FROM "+prefix+"CharSavePoint WHERE CharID="+cid+" AND Slot=2;");require(rows[0].rows[0]==storage::Row{storage::Cell{"77"},storage::Cell{"10"}} && rows[1].rows[0][0]==storage::Cell{"4"} && rows[2].rows[0][0]==storage::Cell{"2"} && rows[3].rows[0][0]==storage::Cell{"4"},"Quick error incorrectly rolled back the character or stopped points");
        // A later point failure rolls back every phase, including partially saved quick rows.
        apply(quick({13,65535,14}));apply(point(3,32760,1,2,3));apply(money(99));apply(skill(7,5));count=packet(0x707);count.insert(count.end(),{1,0,1});apply(count);apply(quest(3));db.begin();bool failed=false;try{save(true);}catch(const std::runtime_error&){failed=true;}require(failed && logs==2 && db.transaction_active(),"Point failure did not follow the logged quick failure");db.rollback();
        require(read_quick().size()==1 && read_quick()[0][3]==storage::Cell{"11"} && cache.interface().points()[3].save_type==1 && cache.inventory().inventory()[0].save_type==2 && cache.skills().saved_count()==2,"Point failure lost old quick rows or pending character state");rows=db.query("SELECT Money,SkillPoint FROM "+prefix+"Chars WHERE CharID="+cid+"; SELECT [Count] FROM "+prefix+"CharItems WHERE CharID="+cid+"; SELECT COUNT(*) FROM "+prefix+"CharSkills WHERE CharID="+cid+"; SELECT [Delay] FROM "+prefix+"CharQuests WHERE CharID="+cid+"; SELECT COUNT(*) FROM "+prefix+"CharSavePoint WHERE CharID="+cid+" AND Slot=3;");require(rows[0].rows[0]==storage::Row{storage::Cell{"77"},storage::Cell{"10"}} && rows[1].rows[0][0]==storage::Cell{"4"} && rows[2].rows[0][0]==storage::Cell{"2"} && rows[3].rows[0][0]==storage::Cell{"2"} && rows[4].rows[0][0]==storage::Cell{"0"},"Point failure retained partial core/item/skill/quest/point writes");
        apply(quick({15,16}));apply(point(3,5,4,5,6));db.begin();result=save(true);db.commit();ack();require(!result.quick_failure && read_quick().size()==2 && read_quick()[0][3]==storage::Cell{"15"} && cache.interface().points()[3].save_type==0,"Composite retry failed");
        apply(point(1,65535,7,8,9));db.begin();save(false);db.commit();ack();rows=db.query("SELECT MapID FROM "+prefix+"CharSavePoint WHERE CharID="+cid+" AND Slot=1; SELECT Number FROM "+prefix+"CharQuickSlots WHERE CharID="+other_id+"; SELECT MapID FROM "+prefix+"CharSavePoint WHERE CharID="+other_id+";");require(rows[0].rows[0][0]==storage::Cell{"2"} && cache.interface().points()[1].map==65535 && cache.interface().save_points_packet()[6]==3 && rows[1].rows[0][0]==storage::Cell{"10"} && rows[2].rows[0][0]==storage::Cell{"9"},"Sentinel map deleted a SQL row or affected another character");
        const auto reject=[&](){db.begin();bool failed=false;try{save(false);}catch(const std::runtime_error&){failed=true;}db.rollback();require(failed,"Invalid point conversion was accepted");};apply(point(1,32768,0,0,0));reject();apply(point(1,65535,0,0,0));apply(point(3,5,std::numeric_limits<float>::infinity(),0,0));reject();
        std::cout<<"Original interface SQL passed: periodic/explicit quick saves, nonfatal partial quick errors, point rollback/retry, legacy coordinates, sentinel and conversion rules\n";
    }catch(const std::exception& error) {std::cerr<<error.what()<<'\n';return 1;}
}
